<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/layout.php';
require_auth();
$pdo=db(); $month=valid_month($_GET['mes']??null);
$q=$pdo->prepare("SELECT COUNT(*) qtd,COALESCE(SUM(amount),0) total FROM opportunities WHERE DATE_FORMAT(opportunity_date,'%Y-%m')=?");$q->execute([$month]);$opps=$q->fetch();
$q=$pdo->prepare("SELECT COUNT(*) qtd,COALESCE(SUM(amount),0) total FROM opportunities WHERE status='Aberta' AND DATE_FORMAT(opportunity_date,'%Y-%m')=?");$q->execute([$month]);$open=$q->fetch();
$q=$pdo->prepare("SELECT COUNT(*) qtd,COALESCE(SUM(amount),0) total FROM orders WHERE invoiced=1 AND DATE_FORMAT(invoice_date,'%Y-%m')=?");$q->execute([$month]);$invoiced=$q->fetch();
$q=$pdo->prepare("SELECT COUNT(*) FROM visits WHERE DATE_FORMAT(visit_date,'%Y-%m')=?");$q->execute([$month]);$visits=(int)$q->fetchColumn();
$funnels=$pdo->query("SELECT f.id,f.label,f.description,COUNT(o.id) qtd,COALESCE(SUM(o.amount),0) total FROM funnels f LEFT JOIN opportunities o ON o.funnel_id=f.id AND o.status='Aberta' WHERE f.active=1 GROUP BY f.id ORDER BY f.sort_order")->fetchAll();
$q=$pdo->prepare("SELECT o.number,o.opportunity_date,o.client_name,o.amount,o.status,pl.name line_name,u.name seller_name FROM opportunities o JOIN product_lines pl ON pl.id=o.product_line_id LEFT JOIN users u ON u.id=o.seller_user_id WHERE DATE_FORMAT(o.opportunity_date,'%Y-%m')=? ORDER BY o.id DESC LIMIT 8");$q->execute([$month]);$recent=$q->fetchAll();
page_header('Painel','painel');
?>
<div class="page-actions"><div><span class="eyebrow">VISÃO COMERCIAL</span><h2>Resumo do mês</h2></div><form method="get" class="inline-form"><label><span>Mês de referência</span><input type="month" name="mes" value="<?= e($month) ?>" onchange="this.form.submit()"></label></form></div>
<div class="kpi-grid"><article class="kpi"><span>Oportunidades</span><strong><?= (int)$opps['qtd'] ?></strong><small><?= money($opps['total']) ?> em volume</small></article><article class="kpi"><span>Pipeline aberto</span><strong><?= (int)$open['qtd'] ?></strong><small><?= money($open['total']) ?> em negociação</small></article><article class="kpi"><span>Faturado</span><strong><?= (int)$invoiced['qtd'] ?></strong><small><?= money($invoiced['total']) ?> no mês</small></article><article class="kpi"><span>Visitas</span><strong><?= $visits ?></strong><small>registradas no mês</small></article></div>
<div class="card"><div class="card-title"><div><span class="tag">FUNIS</span><h3>Oportunidades abertas</h3></div><a class="btn btn-secondary btn-sm" href="orcamentos.php">Abrir oportunidades</a></div><div class="funnel-summary"><?php foreach($funnels as $f): ?><div class="funnel-box"><strong><?= e($f['label']) ?></strong><span><?= e($f['description']) ?></span><div><b><?= (int)$f['qtd'] ?></b> oportunidades · <?= money($f['total']) ?></div></div><?php endforeach; ?></div></div>
<div class="card"><div class="card-title"><div><span class="tag">MOVIMENTO</span><h3>Oportunidades do mês</h3></div></div><?php if(!$recent): ?><?php empty_state('CRM pronto para começar','Não há registros de exemplo. Cadastre a primeira oportunidade para iniciar o painel real.'); ?><?php else: ?><div class="table-wrap"><table><thead><tr><th>Data</th><th>Nº</th><th>Cliente</th><th>Vendedor</th><th>Linha</th><th>Valor</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $row): ?><tr><td><?= e($row['opportunity_date']) ?></td><td class="mono"><?= e($row['number']) ?></td><td><strong><?= e($row['client_name']) ?></strong></td><td><?= e($row['seller_name']?:'—') ?></td><td><?= e($row['line_name']) ?></td><td><?= money($row['amount']) ?></td><td><span class="status status-<?= strtolower(e($row['status'])) ?>"><?= e($row['status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
<?php page_footer(); ?>
